import {walletState} from './followed-wallets.mjs';
export function moneyStatus(row){return row.smartMoney===true?'smart':row.smartMoney===false?'non-smart':'unclassified'}
export function filterUniverse(rows,{query='',source='',interested='',money='',code='',status='',sort='name'}={},now=Date.now()){
 const text=query.trim().toLowerCase();
 return rows.filter(row=>(!text||[row.name,row.address,row.label,row.notes,row.discoveryToken,...(row.aliases||[])].join(' ').toLowerCase().includes(text))&&(!source||(row.sources||[row.source]).includes(source))&&(!interested||Boolean(row.interested)===(interested==='yes'))&&(!money||moneyStatus(row)===money)&&(!code||(code==='none'?!row.code:row.code===code))&&(!status||walletState(row,now)===status)).sort((a,b)=>Number(Boolean(b.interested))-Number(Boolean(a.interested))||(sort==='tokens'?(b.mints?.length||0)-(a.mints?.length||0)||a.name.localeCompare(b.name):sort==='checked'?(b.checkedAt||0)-(a.checkedAt||0)||a.name.localeCompare(b.name):sort==='added'?(b.addedAt||0)-(a.addedAt||0)||a.name.localeCompare(b.name):a.name.localeCompare(b.name)));
}
export function rankActivity(reports){return reports.map(report=>({...report,swaps:report.events.filter(e=>e.kind==='Swap-associated receipt').length,other:report.events.filter(e=>e.kind!=='Swap-associated receipt').length})).sort((a,b)=>b.swaps-a.swaps||b.checked-a.checked||a.address.localeCompare(b.address));}
